import { AbstractSocialCue } from './SocialCue.js';
export class ReadingCue extends AbstractSocialCue {
    constructor(animationManager, settings) {
        super(animationManager, settings);
        this.eyeMovementInterval = null;
    }

    start() {
        this.animationManager.scheduleChange("54", 50, 0, 0);

        let eyePosition = 40;
        let direction = -1; // -1 for left, 1 for right
        let phase = 1; // 1 for left to center, 2 for center to right

        this.eyeMovementInterval = setInterval(() => {
            // Move eyes incrementally
            eyePosition += direction * 5; // Adjust the increment for smoothness

            if (phase === 1 && eyePosition <= 0) { // Move from left to center
                direction = 1; // Change direction to right
                phase = 2; // Switch to center to right phase
            } else if (phase === 2 && eyePosition >= 40) { // Move from center to right
                direction = -1; // Change direction to left
                phase = 1; // Switch to left to center phase
            }

            if (phase === 1) {
                this.animationManager.scheduleChange("61", eyePosition, 0, 0);
            } else {
                this.animationManager.scheduleChange("62", eyePosition, 0, 0);
            }
        }, 150); // Adjust the interval for smoothness
    }

    stop() {
        this.animationManager.scheduleChange("54", 0, 0, 0);

        if (this.eyeMovementInterval) {
            clearInterval(this.eyeMovementInterval);
            this.eyeMovementInterval = null;
        }
        // Reset eye position if needed
        this.animationManager.scheduleChange("61", 0, 0, 0);
        this.animationManager.scheduleChange("62", 0, 0, 0);
    }
}